INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000001', 'LuminaView 65-inch 4K OLED Smart TV', 'TV-OLED-65', 189900, 'Large-screen OLED smart TV with 4K streaming apps, HDMI 2.1 inputs, low-latency gaming mode, and cinematic contrast for lounge rooms.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Smart%20Television.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/SamsungSmartTV.JPG","https://commons.wikimedia.org/wiki/Special:Redirect/file/Samsung%20UE40MU6409U-4617.jpg"]', 'TV & Home Theatre', 7);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000002', 'LuminaView 55-inch QLED Smart TV', 'TV-QLED-55', 119900, 'Bright 55-inch QLED smart TV with voice control, Wi-Fi streaming, Bluetooth audio, and smooth motion handling for sport and movies.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/SamsungSmartTV.JPG","https://commons.wikimedia.org/wiki/Special:Redirect/file/Smart%20Television.jpg"]', 'TV & Home Theatre', 13);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000003', 'ClearSound 2.1 Channel Soundbar', 'AUD-SBAR-21', 24900, 'Compact soundbar and wireless subwoofer package for clearer dialogue, deeper bass, Bluetooth music playback, and simple HDMI ARC setup.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/LG%20LAS260B%20Soundbar.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/SAMSUNG%20SOUNDBAR%20HW-J250.jpg"]', 'Audio', 9);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000004', 'PulseBeat Noise Cancelling Headphones', 'AUD-ANC-01', 19900, 'Over-ear wireless headphones with active noise cancellation, long battery life, multipoint Bluetooth, and fold-flat travel storage.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Jackson%20hedden%20apple%20headphones.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/Bluetooth%20Speaker.jpg"]', 'Audio', 21);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000005', 'BoomPod Portable Bluetooth Speaker', 'AUD-BT-01', 8900, 'Portable speaker with splash resistance, USB-C charging, punchy sound, and party-pair mode for backyard music and travel.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Bluetooth%20Speaker.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/Jackson%20hedden%20apple%20headphones.jpg"]', 'Audio', 16);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000006', 'ViewPro 27-inch QHD USB-C Monitor', 'MON-QHD-27', 32900, '27-inch QHD monitor with USB-C display input, height-adjustable stand, slim bezels, and sharp workspace detail for home offices.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Computer%20monitor.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/Computer%20Screen%20Monitor.jpg"]', 'Computers & Monitors', 11);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000007', 'UltraSpeed HDMI 2.1 Cable 2m', 'CBL-HDMI-2M', 2495, 'Premium 2 metre HDMI 2.1 cable for 4K and 8K video, eARC soundbars, gaming consoles, Blu-ray players, and smart TVs.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/HDMI%20Cable.JPG","https://commons.wikimedia.org/wiki/Special:Redirect/file/HDMI-Connector.jpg"]', 'Cables & Chargers', 58);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000008', 'ConnectPro USB-C 100W Braided Cable', 'CBL-USBC-100W', 2995, 'Durable USB-C cable with 100W charging support for laptops, tablets, phones, docks, and high-speed everyday device charging.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/HDMI-Connector.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/HDMI%20Cable.JPG"]', 'Cables & Chargers', 44);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000009', 'NetNest Wi-Fi 6 Mesh Router 3-Pack', 'NET-MESH-6-3PK', 39900, 'Whole-home Wi-Fi 6 mesh system with three nodes, app setup, parental controls, guest networking, and strong coverage for busy households.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Netgear-Nighthawk-AC1900-WiFi-Router.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/Linksys-Wireless-G-Router.jpg"]', 'Networking', 10);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000010', 'TravelLink AX1500 Wi-Fi 6 Router', 'NET-AX1500-TRVL', 9900, 'Compact travel router with Wi-Fi 6, USB-C power, guest network support, and reliable connectivity for apartments, hotels, and study desks.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Linksys-Wireless-G-Router.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/Netgear-Nighthawk-AC1900-WiFi-Router.jpg"]', 'Networking', 18);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000011', 'FreshStore 519L French Door Fridge', 'APP-FRIDGE-519', 169900, 'Family-sized French door fridge with flexible shelving, humidity-controlled crispers, frost-free cooling, and a clean stainless finish.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Open%20refrigerator%20with%20food%20at%20night.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/Microwave%20oven%2C%20front.JPG"]', 'Kitchen Appliances', 5);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000012', 'WashPro 9kg Front Load Washing Machine', 'APP-WASH-9KG', 89900, 'Efficient 9kg front loader with quick wash cycles, quiet inverter motor, delayed start, and fabric-care programs for family laundry.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Washer.600pix.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/Woodrow%20washing%20machine.jpg"]', 'Laundry Appliances', 8);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000013', 'DrySmart 8kg Heat Pump Dryer', 'APP-DRY-8KG', 119900, 'Energy-efficient heat pump dryer with sensor drying, wool care, anti-crease mode, and gentle low-temperature drying for everyday loads.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Woodrow%20washing%20machine.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/Washer.600pix.jpg"]', 'Laundry Appliances', 4);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000014', 'QuickHeat 32L Inverter Microwave', 'APP-MW-32L', 27900, '32L inverter microwave with even heating, one-touch reheating, defrost programs, and a compact benchtop footprint.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Microwave%20oven%2C%20front.JPG","https://commons.wikimedia.org/wiki/Special:Redirect/file/Coffee%20Machine%20%2820094606532%29.jpg"]', 'Kitchen Appliances', 12);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000015', 'BrewBar Compact Coffee Machine', 'APP-COFFEE-01', 34900, 'Compact coffee machine for quick espresso-style drinks, simple controls, removable water tank, and easy bench-top cleanup.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Coffee%20Machine%20%2820094606532%29.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/Microwave%20oven%2C%20front.JPG"]', 'Small Appliances', 6);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000016', 'CleanJet Cordless Stick Vacuum', 'APP-VAC-01', 44900, 'Cordless stick vacuum with motorised floor head, detachable hand vac, wall dock, and strong suction for carpets and hard floors.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Vacuum%20cleaner.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/Washer.600pix.jpg"]', 'Floorcare', 14);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000017', 'DoorGuard 2K Video Doorbell', 'SMH-DOOR-2K', 17900, 'Smart video doorbell with two-way talk, motion detection, app alerts, night vision, and weather-resistant front door monitoring.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Ring%20video%20doorbell.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/Ring%20Video%20Doorbell%202.jpg"]', 'Smart Home', 17);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000018', 'SecureLatch Smart Door Lock', 'SMH-LOCK-01', 24900, 'Keyless smart lock with app access, PIN codes, auto-locking, guest credentials, and activity history for household security.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/August%202nd-gen%20smart%20lock.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/Ring%20video%20doorbell.jpg"]', 'Smart Home', 3);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000019', 'EnergySense Smart Plug 4-Pack', 'SMH-PLUG-4PK', 7900, 'Four-pack of app-controlled smart plugs for scheduling lamps, heaters, fans, and appliances with voice assistant support.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Smart-plug.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/HDMI%20Cable.JPG"]', 'Smart Home', 26);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000020', 'GlowStrip RGB Smart Light Strip 5m', 'SMH-LIGHT-5M', 6900, 'Five metre RGB smart light strip with app scenes, voice control, music sync, and adhesive backing for shelves and TV units.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Smart-plug.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/Smart%20Television.jpg"]', 'Smart Lighting', 32);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000021', 'StreamCast 4K Media Player', 'TV-STREAM-4K', 8900, 'Compact 4K streaming player with Wi-Fi, voice remote, app store access, and HDMI connection for upgrading older televisions.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Smart%20Television.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/HDMI-Connector.jpg"]', 'TV & Home Theatre', 22);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000022', 'GamePad Wireless Controller', 'GAME-PAD-WL', 9900, 'Wireless game controller with Bluetooth pairing, textured grips, rechargeable battery, and low-latency controls for PC and media setups.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Computer%20Screen%20Monitor.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/SamsungSmartTV.JPG"]', 'Gaming', 15);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000023', 'Cat6 Ethernet Cable 5m', 'CBL-CAT6-5M', 1895, 'Five metre Cat6 Ethernet cable for stable router, console, TV, and desktop network connections where Wi-Fi is not enough.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Linksys-Wireless-G-Router.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/HDMI%20Cable.JPG"]', 'Cables & Chargers', 64);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000024', 'HomeHub Smart Appliance Controller', 'SMH-HUB-01', 14900, 'Smart home hub for coordinating plugs, lights, sensors, locks, and routines from one app with local network discovery.', '["https://commons.wikimedia.org/wiki/Special:Redirect/file/Netgear-Nighthawk-AC1900-WiFi-Router.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/Smart-plug.jpg","https://commons.wikimedia.org/wiki/Special:Redirect/file/Ring%20video%20doorbell.jpg"]', 'Smart Home', 9);
